mapper.select:
select go.id,go.order_no, go.order_status, go.order_time, go.quantity, go.total_price,
go.goods_name, go.goods_img, go.goods_price, go.consignee, go.phone_number,
go.province_code, go.city_code, go.district_code, go.detail_address,
u.nickname as userNickname, ps.nickname as shopName
from goods_orders go
left join user u on go.user_id = u.id
left join pet_shop ps on go.shop_id = ps.id

    and go.order_no =#{orderNo}
    and go.order_status = #{orderStatus}
    and go.order_time > #{orderTime}
    and go.shop_id = #{shopId}

order by go.order_time desc

select id,
       order_status
from goods_orders
where order_status = #{orderStatus}
  and order_time < #{time}

select coalesce(sum(go.total_price), 0) from (
select #{date} date
) d left join goods_orders go on date(go.order_time) = d.date and go.order_status != 5 and go.shop_id = #{shopId} group by d.date order by d.date

select count(go.id) as totalNumber, count(case when go.order_status != 5 then go.id end) as validNumber from (
select #{date} as date
) d left join goods_orders go on date(go.order_time) = d.date and go.shop_id = #{shopId} group by d.date order by d.date

select count(*)
from goods_orders
where shop_id = #{shopId}
  and order_status = #{orderStatus}
